import json,collections
per=collections.Counter(); first=None; slow=[]; ends={}
pre=collections.Counter()
for l in open('app.log'):
    try: d=json.loads(l)
    except: continue
    m=d.get('msg','')
    if 'order_items WHERE order_id = ?' in m:
        per[d['request_id']]+=1; first=first or d['ts']
    if 'order_items WHERE order_id IN' in m: pre[d['ts'][:16]]+=1
    if d['service']=='checkout' and 'request_end' in m and 'summary' in m: ends[d['request_id']]=(d['ts'],d['latency_ms'])
print('first per-row query',first,'reqs',len(per))
import statistics
n=list(per.values());print('queries/req median',statistics.median(n),'max',max(n))
print('batched IN queries last ts',max(pre) if pre else None)
lat=[ends[r][1] for r in per if r in ends];print('summary latency median',statistics.median(lat),'max',max(lat))
pl=[v[1] for r,v in ends.items() if r not in per];print('summary w/o per-row n',len(pl),statistics.median(pl) if pl else None)
E
grep -E '14:2[89]' app.log | grep -E 'ERROR|WARN' | head -5; grep -E 'ERROR' app.log | head -3"
}

